  "Generating...": "\u062C\u0627\u0631\u064D \u0627\u0644\u0625\u0646\u0634\u0627\u0621...",
  "Your result will appear here.": "\u0633\u062A\u0638\u0647\u0631 \u0627\u0644\u0646\u062A\u064A\u062C\u0629 \u0647\u0646\u0627.",
  "Coming Soon": "\u0642\u0631\u064A\u0628\u0627\u064B",
  "This tool is under active development. You'll be notified when it's ready.": "\u0647\u0630\u0647 \u0627\u0644\u0623\u062F\u0627\u0629 \u0642\u064A\u062F \u0627\u0644\u062A\u0637\u0648\u064A\u0631 \u062D\u0627\u0644\u064A\u0627\u064B. \u0633\u0646\u062E\u0628\u0631\u0643 \u0639\u0646\u062F\u0645\u0627 \u062A\u0635\u0628\u062D \u062C\u0627\u0647\u0632\u0629.",
  "AI Writer": "\u0627\u0644\u0643\u0627\u062A\u0628 \u0628\u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064A",
  "Write blogs, articles, and marketing copy.": "\u0627\u0643\u062A\u0628 \u0627\u0644\u0645\u062F\u0648\u0646\u0627\u062A \u0648\u0627\u0644\u0645\u0642\u0627\u0644\u0627\u062A \u0648\u0627\u0644\u0646\u0635\u0648\u0635 \u0627\u0644\u062A\u0633\u0648\u064A\u0642\u064A\u0629.",
