  "Upgrade Now": "\u0627\u0644\u062A\u0631\u0642\u064A\u0629 \u0627\u0644\u0622\u0646",
  "Unlock all 50+ AI tools and unlimited documents.": "\u0627\u0641\u062A\u062D \u062D\u062F\u0648\u062F\u0627\u064B \u0623\u0639\u0644\u0649 \u0648\u0645\u064A\u0632\u0627\u062A \u0627\u062D\u062A\u0631\u0627\u0641\u064A\u0629 \u0625\u0636\u0627\u0641\u064A\u0629.",
  "User": "\u0645\u0633\u062A\u062E\u062F\u0645",
  "Soon": "\u0642\u0631\u064A\u0628\u0627\u064B",
  "Beta": "\u062A\u062C\u0631\u064A\u0628\u064A",
  "Delete My Account": "\u062D\u0630\u0641 \u062D\u0633\u0627\u0628\u064A",
  "This will permanently delete:": "\u0633\u064A\u0624\u062F\u064A \u0647\u0630\u0627 \u0625\u0644\u0649 \u062D\u0630\u0641 \u0645\u0627 \u064A\u0644\u064A \u0646\u0647\u0627\u0626\u064A\u0627\u064B:",
  "Your profile and account credentials": "\u0645\u0644\u0641\u0643 \u0627\u0644\u0634\u062E\u0635\u064A \u0648\u0628\u064A\u0627\u0646\u0627\u062A \u0627\u0639\u062A\u0645\u0627\u062F \u0627\u0644\u062D\u0633\u0627\u0628",
  "All projects (CVs, cover letters, documents)": "\u0643\u0644 \u0627\u0644\u0645\u0634\u0627\u0631\u064A\u0639 (\u0627\u0644\u0633\u064A\u0631 \u0627\u0644\u0630\u0627\u062A\u064A\u0629 \u0648\u062E\u0637\u0627\u0628\u0627\u062A \u0627\u0644\u062A\u063A\u0637\u064A\u0629 \u0648\u0627\u0644\u0645\u0633\u062A\u0646\u062F\u0627\u062A)",
  "All files and exports": "\u0643\u0644 \u0627\u0644\u0645\u0644\u0641\u0627\u062A \u0648\u0627\u0644\u062A\u0635\u062F\u064A\u0631\u0627\u062A",
  "All AI conversations and usage history": "\u0643\u0644 \u0645\u062D\u0627\u062F\u062B\u0627\u062A \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064A \u0648\u0633\u062C\u0644 \u0627\u0644\u0627\u0633\u062A\u062E\u062F\u0627\u0645",
  "All activity logs and preferences": "\u0643\u0644 \u0633\u062C\u0644\u0627\u062A \u0627\u0644\u0646\u0634\u0627\u0637 \u0648\u0627\u0644\u062A\u0641\u0636\u064A\u0644\u0627\u062A",
  "Type": "\u0627\u0643\u062A\u0628",
  "to confirm": "\u0644\u0644\u062A\u0623\u0643\u064A\u062F",
  "Yes, Delete Everything": "\u0646\u0639\u0645\u060C \u0627\u062D\u0630\u0641 \u0643\u0644 \u0634\u064A\u0621",
  "Cancel": "\u0625\u0644\u063A\u0627\u0621",
  "Saving profile...": "\u062C\u0627\u0631\u064D \u062D\u0641\u0638 \u0627\u0644\u0645\u0644\u0641 \u0627\u0644\u0634\u062E\u0635\u064A...",
  "Profile saved": "\u062A\u0645 \u062D\u0641\u0638 \u0627\u0644\u0645\u0644\u0641 \u0627\u0644\u0634\u062E\u0635\u064A",
  "Your name": "\u0627\u0633\u0645\u0643",
  "Email Address": "\u0627\u0644\u0628\u0631\u064A\u062F \u0627\u0644\u0625\u0644\u0643\u062A\u0631\u0648\u0646\u064A",
  "Bio": "\u0646\u0628\u0630\u0629",
  "Tell us about yourself...": "\u0623\u062E\u0628\u0631\u0646\u0627 \u0639\u0646 \u0646\u0641\u0633\u0643...",
  "Save Changes": "\u062D\u0641\u0638 \u0627\u0644\u062A\u063A\u064A\u064A\u0631\u0627\u062A",
  "Updating password...": "\u062C\u0627\u0631\u064D \u062A\u062D\u062F\u064A\u062B \u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631...",
