  "Language": "\u0627\u0644\u0644\u063A\u0629",
  "Dark Mode": "\u0627\u0644\u0648\u0636\u0639 \u0627\u0644\u062F\u0627\u0643\u0646",
  "Light Mode": "\u0627\u0644\u0648\u0636\u0639 \u0627\u0644\u0641\u0627\u062A\u062D",
  "Easy on the eyes": "\u0645\u0631\u064A\u062D \u0644\u0644\u0639\u064A\u0646\u064A\u0646",
