  "Email Notifications": "\u0625\u0634\u0639\u0627\u0631\u0627\u062A \u0627\u0644\u0628\u0631\u064A\u062F \u0627\u0644\u0625\u0644\u0643\u062A\u0631\u0648\u0646\u064A",
  "Important account and security emails": "\u0631\u0633\u0627\u0626\u0644 \u0645\u0647\u0645\u0629 \u0639\u0646 \u0627\u0644\u062D\u0633\u0627\u0628 \u0648\u0627\u0644\u0623\u0645\u0627\u0646",
