  "Stockholm, Sweden": "\u0633\u062A\u0648\u0643\u0647\u0648\u0644\u0645\u060C \u0627\u0644\u0633\u0648\u064A\u062F",
  "Your Email": "\u0628\u0631\u064A\u062F\u0643 \u0627\u0644\u0625\u0644\u0643\u062A\u0631\u0648\u0646\u064A",
