  "Start using 50+ AI tools for free": "\u0627\u0628\u062F\u0623 \u0645\u062C\u0627\u0646\u0627\u064B \u0628\u0623\u062F\u0648\u0627\u062A \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064A \u0627\u0644\u0623\u0633\u0627\u0633\u064A\u0629 \u0648\u0645\u0646\u0634\u0626 \u0627\u0644\u0645\u0648\u0627\u0642\u0639",
