  "Continue with Google": "\u0627\u0644\u0645\u062A\u0627\u0628\u0639\u0629 \u0628\u0627\u0633\u062A\u062E\u062F\u0627\u0645 Google",
  "Email": "\u0627\u0644\u0628\u0631\u064A\u062F \u0627\u0644\u0625\u0644\u0643\u062A\u0631\u0648\u0646\u064A",
  "Sign up free": "\u0633\u062C\u0651\u0644 \u0645\u062C\u0627\u0646\u0627\u064B",
