  "Weak": "\u0636\u0639\u064A\u0641\u0629",
  "Fair": "\u0645\u0642\u0628\u0648\u0644\u0629",
  "Good": "\u062C\u064A\u062F\u0629",
  "Strong": "\u0642\u0648\u064A\u0629",
  "Onboarding": "\u0627\u0644\u0625\u0639\u062F\u0627\u062F \u0627\u0644\u0623\u0648\u0644\u064A",
  "Already have an account? Just wait \u2014 we'll personalize everything.": "\u0644\u062F\u064A\u0643 \u062D\u0633\u0627\u0628 \u0628\u0627\u0644\u0641\u0639\u0644\u061F \u0633\u0646\u062E\u0635\u0635 \u0643\u0644 \u0634\u064A\u0621 \u0644\u0643 \u062A\u0644\u0642\u0627\u0626\u064A\u0627\u064B.",
  "Choose your language": "\u0627\u062E\u062A\u0631 \u0644\u063A\u062A\u0643",
  "You can change this anytime in settings": "\u064A\u0645\u0643\u0646\u0643 \u062A\u063A\u064A\u064A\u0631 \u0630\u0644\u0643 \u0641\u064A \u0623\u064A \u0648\u0642\u062A \u0645\u0646 \u0627\u0644\u0625\u0639\u062F\u0627\u062F\u0627\u062A",
  "What best describes you?": "\u0645\u0627 \u0627\u0644\u0648\u0635\u0641 \u0627\u0644\u0623\u0646\u0633\u0628 \u0644\u0643\u061F",
  "We'll tailor your experience based on this": "\u0633\u0646\u062E\u0635\u0635 \u062A\u062C\u0631\u0628\u062A\u0643 \u0628\u0646\u0627\u0621\u064B \u0639\u0644\u0649 \u0630\u0644\u0643",
  "Tell us about you": "\u0623\u062E\u0628\u0631\u0646\u0627 \u0639\u0646\u0643",
  "Just the basics \u2014 we'll use this to personalize your workspace": "\u0641\u0642\u0637 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062A \u0627\u0644\u0623\u0633\u0627\u0633\u064A\u0629 \u2014 \u0633\u0646\u0633\u062A\u062E\u062F\u0645\u0647\u0627 \u0644\u062A\u062E\u0635\u064A\u0635 \u0645\u0633\u0627\u062D\u0629 \u0639\u0645\u0644\u0643",
  "Country": "\u0627\u0644\u062F\u0648\u0644\u0629",
  "Select your country": "\u0627\u062E\u062A\u0631 \u062F\u0648\u0644\u062A\u0643",
  "Profession": "\u0627\u0644\u0645\u0647\u0646\u0629",
  "e.g. Software Engineer, Student, Designer": "\u0645\u062B\u0644\u0627\u064B: \u0645\u0647\u0646\u062F\u0633 \u0628\u0631\u0645\u062C\u064A\u0627\u062A\u060C \u0637\u0627\u0644\u0628\u060C \u0645\u0635\u0645\u0645",
  "What's your main goal?": "\u0645\u0627 \u0647\u062F\u0641\u0643 \u0627\u0644\u0631\u0626\u064A\u0633\u064A\u061F",
  "Pick one \u2014 we'll recommend the best tools for it": "\u0627\u062E\u062A\u0631 \u0648\u0627\u062D\u062F\u0627\u064B \u0648\u0633\u0646\u0642\u062A\u0631\u062D \u0623\u0641\u0636\u0644 \u0627\u0644\u0623\u062F\u0648\u0627\u062A \u0644\u0647",
  "Your recommended tools": "\u0627\u0644\u0623\u062F\u0648\u0627\u062A \u0627\u0644\u0645\u0642\u062A\u0631\u062D\u0629 \u0644\u0643",
  "Based on your profile, these will help you get started fast": "\u0628\u0646\u0627\u0621\u064B \u0639\u0644\u0649 \u0645\u0644\u0641\u0643\u060C \u0633\u062A\u0633\u0627\u0639\u062F\u0643 \u0647\u0630\u0647 \u0627\u0644\u0623\u062F\u0648\u0627\u062A \u0639\u0644\u0649 \u0627\u0644\u0628\u062F\u0621 \u0628\u0633\u0631\u0639\u0629",
  "You're all set": "\u0643\u0644 \u0634\u064A\u0621 \u062C\u0627\u0647\u0632",
  "Take tour": "\u0627\u0628\u062F\u0623 \u0627\u0644\u062C\u0648\u0644\u0629",
  "Quick Start": "\u0628\u062F\u0621 \u0633\u0631\u064A\u0639",
