  "Publish and verify the application before marking it delivered.": "\u0627\u0646\u0634\u0631 \u0627\u0644\u062A\u0637\u0628\u064A\u0642 \u0648\u062A\u062D\u0642\u0642 \u0645\u0646\u0647 \u0642\u0628\u0644 \u0648\u0636\u0639 \u0639\u0644\u0627\u0645\u0629 \u062A\u0645 \u0627\u0644\u062A\u0633\u0644\u064A\u0645.",
  "Complete every launch readiness check before marking the application delivered.": "\u0623\u0643\u0645\u0644 \u062C\u0645\u064A\u0639 \u0641\u062D\u0648\u0635\u0627\u062A \u062C\u0627\u0647\u0632\u064A\u0629 \u0627\u0644\u0625\u0637\u0644\u0627\u0642 \u0642\u0628\u0644 \u0648\u0636\u0639 \u0639\u0644\u0627\u0645\u0629 \u062A\u0645 \u062A\u0633\u0644\u064A\u0645 \u0627\u0644\u062A\u0637\u0628\u064A\u0642.",
  "Application requirements are incomplete. Restore every required page, form and action before approval.": "\u0645\u062A\u0637\u0644\u0628\u0627\u062A \u0627\u0644\u062A\u0637\u0628\u064A\u0642 \u063A\u064A\u0631 \u0645\u0643\u062A\u0645\u0644\u0629. \u0623\u0639\u062F \u0643\u0644 \u0635\u0641\u062D\u0629 \u0648\u0646\u0645\u0648\u0630\u062C \u0648\u0625\u062C\u0631\u0627\u0621 \u0645\u0637\u0644\u0648\u0628 \u0642\u0628\u0644 \u0627\u0644\u0627\u0639\u062A\u0645\u0627\u062F.",
