  "Saved \xB7 Not live yet": "\u0645\u062D\u0641\u0648\u0638 \xB7 \u0644\u0645 \u064A\u0635\u0628\u062D \u0645\u0628\u0627\u0634\u0631\u064B\u0627 \u0628\u0639\u062F",
