  "AI adaptation instruction": "\u062A\u0639\u0644\u064A\u0645\u0627\u062A \u062A\u0643\u064A\u064A\u0641 \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064A",
