  "New Resume": "\u0633\u064A\u0631\u0629 \u0630\u0627\u062A\u064A\u0629 \u062C\u062F\u064A\u062F\u0629",
  "Translate": "\u062A\u0631\u062C\u0645\u0629",
  "Study Notes": "\u0645\u0644\u0627\u062D\u0638\u0627\u062A \u062F\u0631\u0627\u0633\u0629",
  "Add Item": "\u0625\u0636\u0627\u0641\u0629 \u0639\u0646\u0635\u0631",
  "Resume": "\u0633\u064A\u0631\u0629 \u0630\u0627\u062A\u064A\u0629",
  "Document": "\u0645\u0633\u062A\u0646\u062F",
  "Translation": "\u062A\u0631\u062C\u0645\u0629",
  "No items in this project": "\u0644\u0627 \u062A\u0648\u062C\u062F \u0639\u0646\u0627\u0635\u0631 \u0641\u064A \u0647\u0630\u0627 \u0627\u0644\u0645\u0634\u0631\u0648\u0639",
  "Add resumes, cover letters, notes, AI chats and more to organize your work.": "\u0623\u0636\u0641 \u0627\u0644\u0633\u064A\u0631 \u0627\u0644\u0630\u0627\u062A\u064A\u0629 \u0648\u062E\u0637\u0627\u0628\u0627\u062A \u0627\u0644\u062A\u063A\u0637\u064A\u0629 \u0648\u0627\u0644\u0645\u0644\u0627\u062D\u0638\u0627\u062A \u0648\u0645\u062D\u0627\u062F\u062B\u0627\u062A AI \u0648\u063A\u064A\u0631\u0647\u0627 \u0644\u062A\u0646\u0638\u064A\u0645 \u0639\u0645\u0644\u0643.",
  "Add First Item": "\u0625\u0636\u0627\u0641\u0629 \u0623\u0648\u0644 \u0639\u0646\u0635\u0631",
  "Empty Trash": "\u0625\u0641\u0631\u0627\u063A \u0633\u0644\u0629 \u0627\u0644\u0645\u062D\u0630\u0648\u0641\u0627\u062A",
  "Current role": "\u0627\u0644\u0648\u0638\u064A\u0641\u0629 \u0627\u0644\u062D\u0627\u0644\u064A\u0629",
  "Font Family": "\u0646\u0648\u0639 \u0627\u0644\u062E\u0637",
  "Section Order": "\u062A\u0631\u062A\u064A\u0628 \u0627\u0644\u0623\u0642\u0633\u0627\u0645",
  "Processing with AI...": "\u062C\u0627\u0631\u064D \u0627\u0644\u0645\u0639\u0627\u0644\u062C\u0629 \u0628\u0627\u0633\u062A\u062E\u062F\u0627\u0645 AI...",
  "View Cover Letter": "\u0639\u0631\u0636 \u062E\u0637\u0627\u0628 \u0627\u0644\u062A\u063A\u0637\u064A\u0629",
  "Analyzing your resume against the job description...": "\u062C\u0627\u0631\u064D \u062A\u062D\u0644\u064A\u0644 \u0633\u064A\u0631\u062A\u0643 \u0627\u0644\u0630\u0627\u062A\u064A\u0629 \u0645\u0642\u0627\u0631\u0646\u0629 \u0628\u0648\u0635\u0641 \u0627\u0644\u0648\u0638\u064A\u0641\u0629...",
  "Suggestions": "\u0627\u0642\u062A\u0631\u0627\u062D\u0627\u062A",
  "Save Current": "\u062D\u0641\u0638 \u0627\u0644\u062D\u0627\u0644\u064A",
  "Your resume looks great! No issues found.": "\u0633\u064A\u0631\u062A\u0643 \u0627\u0644\u0630\u0627\u062A\u064A\u0629 \u062A\u0628\u062F\u0648 \u0645\u0645\u062A\u0627\u0632\u0629! \u0644\u0645 \u064A\u062A\u0645 \u0627\u0644\u0639\u062B\u0648\u0631 \u0639\u0644\u0649 \u0645\u0634\u0643\u0644\u0627\u062A.",
  "Excellent": "\u0645\u0645\u062A\u0627\u0632",
